import{_ as i,o as s,c as a,a2 as t}from"./chunks/framework.Dt6pBwm7.js";const u=JSON.parse('{"title":"Publishing the documentation","description":"","frontmatter":{},"headers":[],"relativePath":"guides/publishing.md","filePath":"guides/publishing.md"}'),o={name:"guides/publishing.md"};function n(l,e,r,d,h,c){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="publishing-the-documentation" tabindex="-1">Publishing the documentation <a class="header-anchor" href="#publishing-the-documentation" aria-label="Permalink to &quot;Publishing the documentation&quot;">​</a></h1><h2 id="anonymized-examples-and-search-engine-policy" tabindex="-1">Anonymized examples and search-engine policy <a class="header-anchor" href="#anonymized-examples-and-search-engine-policy" aria-label="Permalink to &quot;Anonymized examples and search-engine policy&quot;">​</a></h2><p>All documentation uses anonymized company and library names, including package names, custom-element tags, and URLs inside code examples. These names are placeholders: the published examples are not directly runnable without mapping them back to the real private dependencies. Imported source blocks are anonymized during syntax highlighting; the application source is not renamed. The same warning appears in the footer of every page.</p><p>Every generated HTML page, including the custom 404 page, carries <code>noindex, nofollow, noarchive</code> metadata for general crawlers and Googlebot. A <code>robots.txt</code> file requests that crawlers do not crawl the site. Since this is a GitHub Pages project site, <code>/table-docs/robots.txt</code> is not the authoritative host-level <code>/robots.txt</code>; the page-level <code>noindex</code> directives provide the indexing policy independently of that file.</p><p>These are requests to cooperative search engines, not authentication or a privacy boundary. They cannot guarantee that the site never appears in search results, remove already indexed URLs immediately, stop noncompliant crawlers, or hide the public repository. Existing indexed results may require removal requests through the search engine&#39;s webmaster tools. Use private hosting with authentication if the content must be inaccessible publicly.</p><p>The workflow runs <code>node tools/verify-docs.mjs</code> before publishing. It checks all built HTML, JavaScript, JSON, CSS, and other text assets for unredacted names, and verifies the indexing metadata and crawler file. A failure prevents deployment and preserves the previous public site.</p><p>The public documentation lives at <a href="https://airafa.github.io/table-docs/" target="_blank" rel="noreferrer">https://airafa.github.io/table-docs/</a>. The public <a href="https://github.com/airafa/table-docs" target="_blank" rel="noreferrer">airafa/table-docs</a> repository contains only the generated VitePress site, including the rendered code examples. The application source remains in the private source repository.</p><h2 id="deployment-flow" tabindex="-1">Deployment flow <a class="header-anchor" href="#deployment-flow" aria-label="Permalink to &quot;Deployment flow&quot;">​</a></h2><ol><li>A pull request builds the documentation and checks internal links.</li><li>A push to <code>main</code> builds and publishes the generated site. Changes to source files also trigger a build because the tutorial imports those files as code examples.</li><li>GitHub Pages serves the public repository&#39;s <code>main</code> branch at its root. The generated <code>.nojekyll</code> file disables Jekyll processing.</li></ol><p>You can also run <strong>Publish documentation</strong> manually from the source repository&#39;s Actions tab. Manual runs publish only when the selected branch is <code>main</code>.</p><p>The workflow installs only the locked public dependencies in <code>docs/package.json</code>. It does not install the application&#39;s private packages or need a private registry token. The checked-in <code>docs/package-lock.json</code> is maintained with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspaces=false</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --package-lock-only</span></span></code></pre></div><p>The workflow sets <code>DOCS_BASE=/table-docs/</code> so links, scripts, styles, and local search work under the GitHub Pages project path. Local development defaults to <code>/</code>. To reproduce the deployed build:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspaces=false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DOCS_BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/table-docs/</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span></span></code></pre></div><p>Open the preview&#39;s <code>/table-docs/</code> path, not its root.</p><h2 id="deployment-credentials" tabindex="-1">Deployment credentials <a class="header-anchor" href="#deployment-credentials" aria-label="Permalink to &quot;Deployment credentials&quot;">​</a></h2><p>The source repository&#39;s <code>DOCS_DEPLOY_KEY</code> Actions secret is an SSH private key. Its public half is a write-enabled deploy key on <code>airafa/table-docs</code> only. It does not grant access to other repositories. Pull requests never run the deployment step, and checkout does not persist its GitHub token.</p><p>To rotate the key:</p><ol><li>Generate a new dedicated Ed25519 SSH key pair.</li><li>Add its public half to <strong>Settings &gt; Deploy keys</strong> in <code>airafa/table-docs</code>, enabling write access.</li><li>Replace the source repository&#39;s <code>DOCS_DEPLOY_KEY</code> Actions secret with the private half.</li><li>Run the workflow on <code>main</code> and verify the site.</li><li>Remove the old deploy key and securely remove local private-key files.</li></ol><p>Never commit either a private key or an access token.</p><h2 id="verification-and-troubleshooting" tabindex="-1">Verification and troubleshooting <a class="header-anchor" href="#verification-and-troubleshooting" aria-label="Permalink to &quot;Verification and troubleshooting&quot;">​</a></h2><ul><li>Check <strong>Publish documentation</strong> in the private source repository&#39;s Actions tab.</li><li>Check the Pages deployment in the public repository&#39;s Actions tab.</li><li>Verify the home page, a tutorial chapter, navigation, and local search at <a href="https://airafa.github.io/table-docs/" target="_blank" rel="noreferrer">https://airafa.github.io/table-docs/</a>.</li><li>A build failure does not replace the last successful public site.</li><li>A deployment permission failure usually means the deploy key is missing, revoked, or does not have write access.</li><li>A missing stylesheet or broken navigation usually indicates an incorrect <code>DOCS_BASE</code>; use <code>/table-docs/</code> for this repository.</li><li>If GitHub Pages is disabled, configure deployment from branch <code>main</code>, folder <code>/</code>, in the public repository&#39;s <strong>Settings &gt; Pages</strong>.</li></ul><p>Publishing exposes the built documentation, including embedded source examples and configuration. Review new content for public suitability before merging.</p>`,23)])])}const g=i(o,[["render",n]]);export{u as __pageData,g as default};
